int process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_auth_ticket_handler *handler = NULL;
    struct ceph_ticket *ticket = NULL;
    struct ceph_crypto_key *new_key = NULL;
    void *decrypted = NULL;
    size_t decrypted_len = 0;

    if (!ac || !secret || !p || !*p || *p >= end) {
        goto out;
    }

    if (end - *p < sizeof(*ticket)) {
        goto out;
    }

    ticket = (struct ceph_ticket *)*p;
    *p += sizeof(*ticket);

    if (le32_to_cpu(ticket->magic) != CEPH_AUTH_TICKET_MAGIC) {
        goto out;
    }

    handler = get_ticket_handler(ac, le32_to_cpu(ticket->type));
    if (!handler) {
        goto out;
    }

    if (le32_to_cpu(ticket->encrypted)) {
        decrypted_len = le32_to_cpu(ticket->encrypted_len);
        decrypted = malloc(decrypted_len);
        if (!decrypted) {
            ret = -ENOMEM;
            goto out;
        }

        ret = decrypt_ticket(secret, *p, end - *p, decrypted, &decrypted_len);
        if (ret < 0) {
            goto out;
        }

        *p = decrypted;
        end = *p + decrypted_len;
    }

    if (end - *p < sizeof(*new_key)) {
        goto out;
    }

    new_key = (struct ceph_crypto_key *)*p;
    *p += sizeof(*new_key);

    if (new_key->len > CEPH_CRYPTO_MAX_KEY_LEN) {
        goto out;
    }

    if (end - *p < new_key->len) {
        goto out;
    }

    if (new_key->len > 0) {
        new_key->data = *p;
        *p += new_key->len;
    }

    handler->session_key = new_key;
    handler->ticket_blob = *p;
    handler->ticket_blob_len = end - *p;

    ret = 0;

out:
    if (decrypted) {
        free(decrypted);
    }
    return ret;
}
